// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.aggregate.ext;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.vocabulary.AGGF;
import org.eclipse.rdf4j.query.parser.sparql.aggregate.AggregateFunctionFactory;
import org.eclipse.rdf4j.query.parser.sparql.aggregate.AggregateNAryFunctionFactory;
import org.eclipse.rdf4j.query.parser.sparql.aggregate.CustomAggregateFunctionRegistry;
import org.eclipse.rdf4j.query.parser.sparql.aggregate.CustomAggregateNAryFunctionRegistry;
import org.junit.jupiter.api.Test;

/**
 * Wiring contract of the {@code agg:} extension aggregates: service files, registries, vocabulary constants and
 * instantiability all agree with each other.
 */
class ExtensionAggregateContractTest {

	private static final String SERVICES = "META-INF/services/";

	private static final String UNARY_SERVICE = SERVICES + AggregateFunctionFactory.class.getName();

	private static final String NARY_SERVICE = SERVICES + AggregateNAryFunctionFactory.class.getName();

	private static final String EXT_PACKAGE = ExtensionAggregateContractTest.class.getPackageName();

	private static final Set<String> NON_EXT_AGGF_LOCAL_NAMES = Set.of("stdev", "stdev_population", "variance",
			"variance_population");

	private static List<String> serviceEntries(String resource) throws IOException {
		List<String> entries = new ArrayList<>();
		InputStream in = ExtensionAggregateContractTest.class.getClassLoader().getResourceAsStream(resource);
		assertThat(in).as(resource).isNotNull();
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
			String line;
			while ((line = reader.readLine()) != null) {
				String trimmed = line.trim();
				if (!trimmed.isEmpty() && !trimmed.startsWith("#")) {
					entries.add(trimmed);
				}
			}
		}
		return entries;
	}

	private static List<String> extEntries(String resource) throws IOException {
		List<String> ext = new ArrayList<>();
		for (String entry : serviceEntries(resource)) {
			if (entry.startsWith(EXT_PACKAGE + ".")) {
				ext.add(entry);
			}
		}
		return ext;
	}

	private static Set<IRI> aggfConstants() throws IllegalAccessException {
		Set<IRI> iris = new HashSet<>();
		for (Field field : AGGF.class.getDeclaredFields()) {
			if (Modifier.isStatic(field.getModifiers()) && field.getType() == IRI.class) {
				iris.add((IRI) field.get(null));
			}
		}
		return iris;
	}

	@Test
	void unaryServiceEntriesAreInstantiableResolvableFactories() throws Exception {
		List<String> entries = extEntries(UNARY_SERVICE);
		assertThat(entries).hasSize(10);
		for (String className : entries) {
			Object instance = Class.forName(className).getDeclaredConstructor().newInstance();
			assertThat(instance).as(className).isInstanceOf(AbstractUnaryAggregateFactory.class);
			AbstractUnaryAggregateFactory factory = (AbstractUnaryAggregateFactory) instance;
			assertThat(factory.getIri()).as(className).startsWith(AGGF.NAMESPACE);
			Optional<AggregateFunctionFactory> registered = CustomAggregateFunctionRegistry.getInstance()
					.get(factory.getIri());
			assertThat(registered).as(factory.getIri()).isPresent();
			assertThat(registered.get()).isInstanceOf(factory.getClass());
			assertThat(factory.getCollector()).as(className).isInstanceOf(ExtensionCollector.class);
			assertThat(factory.buildFunction(bs -> null)).as(className).isNotNull();
		}
	}

	@Test
	void naryServiceEntriesAreInstantiableResolvableBinaryFactories() throws Exception {
		List<String> entries = extEntries(NARY_SERVICE);
		assertThat(entries).hasSize(8);
		for (String className : entries) {
			Object instance = Class.forName(className).getDeclaredConstructor().newInstance();
			assertThat(instance).as(className).isInstanceOf(AbstractNAryAggregateFactory.class);
			AbstractNAryAggregateFactory factory = (AbstractNAryAggregateFactory) instance;
			assertThat(factory.getIri()).as(className).startsWith(AGGF.NAMESPACE);
			Optional<AggregateNAryFunctionFactory> registered = CustomAggregateNAryFunctionRegistry.getInstance()
					.get(factory.getIri());
			assertThat(registered).as(factory.getIri()).isPresent();
			assertThat(registered.get()).isInstanceOf(factory.getClass());
			assertThat(factory.getMinNumberOfArguments()).as(className).isEqualTo(2);
			assertThat(factory.getMaxNumberOfArguments()).as(className).isEqualTo(2);
			assertThat(factory.getCollector()).as(className).isInstanceOf(ExtensionCollector.class);
			assertThat(factory.buildFunction((i, bs) -> null)).as(className).isNotNull();
		}
	}

	@Test
	void serviceFilesAreDisjointAndFreeOfDuplicates() throws Exception {
		List<String> unary = serviceEntries(UNARY_SERVICE);
		List<String> nary = serviceEntries(NARY_SERVICE);
		assertThat(unary).doesNotHaveDuplicates();
		assertThat(nary).doesNotHaveDuplicates();
		assertThat(unary).doesNotContainAnyElementsOf(nary);
		// an aggregate IRI is served by exactly one of the two registries
		Set<String> unaryIris = new HashSet<>();
		for (String className : unary) {
			unaryIris.add(((AggregateFunctionFactory) Class.forName(className)
					.getDeclaredConstructor()
					.newInstance()).getIri());
		}
		for (String className : nary) {
			String iri = ((AggregateNAryFunctionFactory) Class.forName(className)
					.getDeclaredConstructor()
					.newInstance()).getIri();
			assertThat(unaryIris).as(iri).doesNotContain(iri);
			assertThat(CustomAggregateFunctionRegistry.getInstance().get(iri)).as(iri).isEmpty();
		}
		for (String iri : unaryIris) {
			assertThat(CustomAggregateNAryFunctionRegistry.getInstance().get(iri)).as(iri).isEmpty();
		}
	}

	@Test
	void vocabularyConstantsMatchFactoryIris() throws Exception {
		Set<IRI> constants = aggfConstants();
		Set<String> factoryIris = new HashSet<>();
		for (String className : extEntries(UNARY_SERVICE)) {
			factoryIris.add(((AggregateFunctionFactory) Class.forName(className)
					.getDeclaredConstructor()
					.newInstance()).getIri());
		}
		for (String className : extEntries(NARY_SERVICE)) {
			factoryIris.add(((AggregateNAryFunctionFactory) Class.forName(className)
					.getDeclaredConstructor()
					.newInstance()).getIri());
		}
		assertThat(factoryIris).hasSize(18);
		for (String iri : factoryIris) {
			assertThat(constants).as("AGGF constant for " + iri).anyMatch(c -> c.stringValue().equals(iri));
		}
		// every agg: constant, including the pre-existing stdev/variance ones, resolves to a registered aggregate
		for (IRI constant : constants) {
			String iri = constant.stringValue();
			assertThat(iri).startsWith(AGGF.NAMESPACE);
			boolean unary = CustomAggregateFunctionRegistry.getInstance().get(iri).isPresent();
			boolean nary = CustomAggregateNAryFunctionRegistry.getInstance().get(iri).isPresent();
			assertThat(unary || nary).as(iri + " registered").isTrue();
			if (!NON_EXT_AGGF_LOCAL_NAMES.contains(constant.getLocalName())) {
				assertThat(factoryIris).as(iri + " served by an ext factory").contains(iri);
			}
		}
		assertThat(constants).hasSize(18 + NON_EXT_AGGF_LOCAL_NAMES.size());
		// constants are named after their local names
		for (Field field : AGGF.class.getDeclaredFields()) {
			if (Modifier.isStatic(field.getModifiers()) && field.getType() == IRI.class) {
				assertThat(((IRI) field.get(null)).getLocalName()).isEqualTo(field.getName());
			}
		}
	}

	@Test
	void everyExtFactoryClassIsListedInAServiceFile() throws Exception {
		Set<String> listed = new HashSet<>(extEntries(UNARY_SERVICE));
		listed.addAll(extEntries(NARY_SERVICE));
		for (Class<?> factory : List.of(MedianAggregateFactory.class, ModeAggregateFactory.class,
				CountIfAggregateFactory.class, BoolAndAggregateFactory.class, BoolOrAggregateFactory.class,
				FirstAggregateFactory.class, LastAggregateFactory.class, ApproxCountDistinctAggregateFactory.class,
				HistogramAggregateFactory.class, ArrayAggAggregateFactory.class,
				PercentileContAggregateFactory.class, PercentileDiscAggregateFactory.class,
				ApproxQuantileAggregateFactory.class, CorrAggregateFactory.class, CovarPopAggregateFactory.class,
				CovarSampAggregateFactory.class, ArgMinAggregateFactory.class, ArgMaxAggregateFactory.class)) {
			assertThat(listed).contains(factory.getName());
		}
		assertThat(listed).hasSize(18);
	}
}
